shapes.TrackingInfoList = { t = "list", item = S.ref("TrackingInfo") }
shapes.TransactionInfo = {
  t = "struct",
  name = "TransactionInfo",
  members = {
    { name = "buyer_transaction_id", schema = S.string },
    { name = "seller_transaction_id", schema = S.string },
    { name = "reference_id", schema = S.string },
    { name = "create_time", schema = S.string },
    { name = "transaction_status", schema = S.ref("TransactionInfoTransactionStatus") },
    { name = "gross_amount", schema = S.ref("Money") },
    { name = "gross_asset", schema = S.ref("Cryptocurrency") },
    { name = "invoice_number", schema = S.string },
    { name = "custom", schema = S.string },
    { name = "buyer", schema = S.ref("Buyer") },
    { name = "seller", schema = S.ref("Seller") },
    { name = "items", schema = S.ref("ItemInfoList") },
    { name = "payment_processor", schema = S.unknown },
  },
}
shapes.TransactionInfoList = { t = "list", item = S.ref("TransactionInfo") }
shapes.TransactionInfoTransactionStatus = {
  t = "enum",
  base = "string",
  values = {
    "COMPLETED",
    "UNCLAIMED",
    "DENIED",
    "FAILED",
    "HELD",
    "PENDING",
    "PARTIALLY_REFUNDED",
    "REFUNDED",
    "REVERSED",
    "CANCELLED",
  },
}

local classes = {}

classes.BadRequest = errors.define({
  tag = "BadRequest",
  categories = { "BadRequestError" },
  matchers = { { status = 400 } },
})
classes.NotFound = errors.define({
  tag = "NotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 404 } },
})
classes.UnprocessableEntity = errors.define({
  tag = "UnprocessableEntity",
  categories = { "BadRequestError" },
  matchers = { { status = 422 } },
})

